// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openOwnersList, openOwnerDetail } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(1202000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState("networkidle");

    await openOwnersList(page);
    await expect(page.getByRole("cell", { name: "Max Samantha" })).toContainText("Max");

    await openOwnerDetail(page, "/petclinic/owners/6");

    // Landed on the owner detail page -- the only route that renders app-pet-list.
    await expect(page).toHaveURL(/\/petclinic\/owners\/6$/);

    // The owner's own record must be painted, not just the static chrome.
    await expect(page.locator(".ownerFullName")).toHaveText("Jean Coleman");

    // Jean Coleman owns two pets, so app-pet-list must render twice.
    await expect(page.locator("app-pet-list")).toHaveCount(2);

    // The Nickname row added by this PR must be visible with its pet's name.
    await expect(page.locator("app-pet-list").first()).toContainText("Nickname");
    await expect(page.locator("app-pet-list").first()).toContainText("Max");
});
